def update_content_types(apps, schema_editor):
    ContentType = apps.get_model('contenttypes', 'ContentType')
    for model_name in MOVED_MODELS:
        old_ct = ContentType.objects.filter(app_label='Evidencia', model=model_name).first()
        new_ct = ContentType.objects.filter(app_label='kompresory', model=model_name).first()
        if old_ct and new_ct:
            new_ct.delete()
            old_ct.app_label = 'kompresory'
            old_ct.save(update_fields=['app_label'])
        elif old_ct:
            old_ct.app_label = 'kompresory'
            old_ct.save(update_fields=['app_label'])


def reverse_content_types(apps, schema_editor):
    ContentType = apps.get_model('contenttypes', 'ContentType')
    for model_name in MOVED_MODELS:
        ContentType.objects.filter(app_label='kompresory', model=model_name).update(app_label='Evidencia')


